"""Expected values transcribed from Table 2, not generated by the implementation."""
import json
import math
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
import personal_report as report
import presets

MANIFEST = json.loads((ROOT / "skill.json").read_text())


@pytest.mark.parametrize("lower,upper,hr,low,high", [
    (15.0, 18.5, 1.51, 1.43, 1.59),
    (18.5, 20.0, 1.13, 1.09, 1.17),
    (20.0, 22.5, 1.00, 0.98, 1.02),
    (22.5, 25.0, 1.00, 0.99, 1.01),
    (25.0, 27.5, 1.07, 1.07, 1.08),
    (27.5, 30.0, 1.20, 1.18, 1.22),
    (30.0, 35.0, 1.45, 1.41, 1.48),
    (35.0, 40.0, 1.94, 1.87, 2.01),
    (40.0, 60.0, 2.76, 2.60, 2.92),
])
def test_table_2_printed_categories(lower, upper, hr, low, high):
    # Printed category inputs are intervals; test their inclusive lower edges.
    # This reproduces the published lookup, not the original cohort model fit.
    row = report.lookup(lower)
    assert row == (lower, upper, hr, low, high)
    assert report.lookup((lower + upper) / 2) == row
    assert report.lookup(math.nextafter(upper, lower)) == row


def run(tmp_path, rows="height_cm,200,cm\nweight_kg,120,kg\n", extra=None):
    path = tmp_path / "measurements.csv"
    path.write_text("marker,value,unit\n" + rows)
    args = [sys.executable, str(ROOT / "scripts/personal_report.py"),
            "--measurements", str(path), "--age", "50", "--smoking", "never",
            "--chronic-disease", "no", "--out", str(tmp_path / "out")]
    return subprocess.run(args + (extra or []), capture_output=True, text=True)


def test_manifest_matches_presets():
    declared = {x["key"]: x["unit"] for x in MANIFEST["inputs"] if x["from"] == "measurements"}
    assert declared == presets.INPUT_UNITS
    assert MANIFEST["inputs_status"] == "verified"


def test_cli_result_and_card(tmp_path):
    assert run(tmp_path).returncode == 0
    data = json.loads((tmp_path / "out/result.json").read_text())["outputs"]
    # Synthetic height/weight fixture lands at the printed Table 2 lower edge 30.0.
    assert data["bmi_kg_m2"]["value"] == 30.0
    assert data["category_hr"]["value"] == 1.45
    assert data["category_hr_ci_low"]["value"] == 1.41
    assert data["category_hr_ci_high"]["value"] == 1.48
    text = (tmp_path / "out/report.md").read_text()
    assert text.index("论文卡片") < text.index("你的测量")
    assert "10.1016/s0140-6736(16)30175-1" in text
    assert "边界:" in text and presets.BOUNDARY in text


@pytest.mark.parametrize("rows,extra", [
    ("height_cm,200,cm\nweight_kg,120,mmol/L\n", []),
    ("height_cm,2000,cm\nweight_kg,120,kg\n", []),
    ("height_cm,200,cm\n", []),
    ("height_cm,200,cm\nweight_kg,nan,kg\n", []),
    ("height_cm,200,cm\nweight_kg,240,kg\n", []),
    ("height_cm,200,cm\nweight_kg,59,kg\n", []),
    ("height_cm,200,cm\nweight_kg,120,kg\n", ["--age", "90"]),
    ("height_cm,200,cm\nweight_kg,120,kg\n", ["--age", "nan"]),
    ("height_cm,200,cm\nweight_kg,120,kg\n", ["--age", "bad"]),
    ("height_cm,200,cm\nweight_kg,120,kg\n", ["--smoking", "former"]),
    ("height_cm,200,cm\nweight_kg,120,kg\n", ["--smoking", "unknown"]),
    ("height_cm,200,cm\nweight_kg,120,kg\n", ["--chronic-disease", "yes"]),
])
def test_invalid_or_outside_population_exits_three(tmp_path, rows, extra):
    assert run(tmp_path, rows, extra).returncode == 3
    assert (tmp_path / "out/problems.json").exists()
    data = json.loads((tmp_path / "out/result.json").read_text())["outputs"]
    assert all(x["value"] is None for x in data.values())
    assert not (tmp_path / "out/levers.json").exists()
    text = (tmp_path / "out/report.md").read_text()
    assert "论文卡片" in text and "边界:" in text
    assert "该档人群 HR：" not in text


def test_unit_conversion_and_aliases(tmp_path):
    assert run(tmp_path, "身高,2,m\n体重,120000,g\n").returncode == 0
    data = json.loads((tmp_path / "out/result.json").read_text())["outputs"]
    assert data["bmi_kg_m2"]["value"] == 30.0
    assert data["category_hr"]["value"] == 1.45


def test_weight_scenario_uses_printed_bins(tmp_path):
    target = tmp_path / "targets.csv"
    target.write_text("marker,value,unit\n体重,110,kg\n")
    assert run(tmp_path, extra=["--targets", str(target)]).returncode == 0
    data = json.loads((tmp_path / "out/levers.json").read_text())
    assert data["schema"] == "longevity-levers/1"
    assert data["current"]["category_hr"] == 1.45
    assert data["targets"]["bmi_kg_m2"] == 27.5
    assert data["targets"]["category_hr"] == 1.20
    assert data["levers"][0]["category_hr_delta"] == pytest.approx(1.20 - 1.45)
    assert len(data["sensitivity"]) == 2
    assert all(x["category_hr_per_unit"] is None for x in data["sensitivity"])
    assert "不是" in data["note_zh"]


def test_stale_outputs_removed_on_error(tmp_path):
    assert run(tmp_path).returncode == 0
    assert run(tmp_path, "height_cm,200,cm\n").returncode == 3
    assert not (tmp_path / "out/levers.json").exists()


def test_unknown_target_and_bad_target_stop(tmp_path):
    target = tmp_path / "targets.csv"
    for row in ("腰围,90,cm", "weight_kg,240,kg", "height_cm,190,cm"):
        target.write_text("marker,value,unit\n" + row + "\n")
        assert run(tmp_path, extra=["--targets", str(target)]).returncode == 3


def test_missing_arguments_are_structured(tmp_path):
    proc = subprocess.run([sys.executable, str(ROOT / "scripts/personal_report.py"),
                           "--out", str(tmp_path / "out")], capture_output=True)
    assert proc.returncode == 3
    problems = json.loads((tmp_path / "out/problems.json").read_text())["problems"]
    assert {p["key"] for p in problems} >= {"height_cm", "weight_kg", "age", "smoking", "chronic_disease"}


@pytest.mark.parametrize("height,weight,hr,low,high", [
    # Exact printed Table 2 lower cutpoints reached by real height/weight pairs;
    # the lower bound is inclusive, so the HR is the upper band's printed cell.
    ("160", "64", 1.07, 1.07, 1.08),     # BMI 25.0 -> 25.0-<27.5
    ("160", "57.6", 1.00, 0.99, 1.01),   # BMI 22.5 -> 22.5-<25.0
    ("155", "48.05", 1.00, 0.98, 1.02),  # BMI 20.0 -> 20.0-<22.5
    ("160", "38.4", 1.51, 1.43, 1.59),   # BMI 15.0 -> 15.0-<18.5 (in range)
])
def test_exact_cutpoints_use_inclusive_lower_band(tmp_path, height, weight, hr, low, high):
    rows = f"height_cm,{height},cm\nweight_kg,{weight},kg\n"
    assert run(tmp_path, rows).returncode == 0
    data = json.loads((tmp_path / "out/result.json").read_text())["outputs"]
    assert data["category_hr"]["value"] == hr
    assert data["category_hr_ci_low"]["value"] == low
    assert data["category_hr_ci_high"]["value"] == high
